def minFlips(grid: List[List[int]]) -> int:
    m = len(grid)
    n = len(grid[0])

    def calc_row_flips():
        # For each row, pair columns j and n-1-j
        # For each pair, we need to make them equal.
        # If they are the same, 0 flips. If different, 1 flip.
        # But wait, we want all rows to be palindromic.
        # For a single row to be palindromic, for each pair (j, n-1-j), the values must be equal.
        # So for each pair, if grid[i][j] != grid[i][n-1-j], we need 1 flip.
        # Total flips = sum over all rows and all pairs of (1 if different else 0)
        flips = 0
        for i in range(m):
            for j in range(n // 2):
                if grid[i][j] != grid[i][n - 1 - j]:
                    flips += 1
        return flips

    def calc_col_flips():
        # For each column, pair rows i and m-1-i
        # For each pair, if grid[i][j] != grid[m-1-i][j], we need 1 flip.
        flips = 0
        for j in range(n):
            for i in range(m // 2):
                if grid[i][j] != grid[m - 1 - i][j]:
                    flips += 1
        return flips

    return min(calc_row_flips(), calc_col_flips())
