from typing import List

def minFlips(grid: List[List[int]]) -> int:
    m = len(grid)
    n = len(grid[0]) if m > 0 else 0

    # Option 1: Make all rows palindromic
    # For each row, we need to make it palindromic.
    # The cost for a row is determined by the pairs (j, n-1-j).
    # For each pair, if grid[i][j] != grid[i][n-1-j], we need 1 flip.
    # If n is odd, the middle element doesn't need any flip for row palindrome.

    row_cost = 0
    for i in range(m):
        for j in range(n // 2):
            if grid[i][j] != grid[i][n - 1 - j]:
                row_cost += 1

    # Option 2: Make all columns palindromic
    # For each column, we need to make it palindromic.
    # The cost for a column is determined by the pairs (i, m-1-i).
    # If m is odd, the middle element doesn't need any flip for column palindrome.

    col_cost = 0
    for j in range(n):
        for i in range(m // 2):
            if grid[i][j] != grid[m - 1 - i][j]:
                col_cost += 1

    return min(row_cost, col_cost)
