def smallestString(s: str):
    n = len(s)

    # Find the first non-'a' character
    first_non_a = -1
    for i in range(n):
        if s[i] != 'a':
            first_non_a = i
            break

    # If all characters are 'a', we must operate on the last character
    if first_non_a == -1:
        # Convert the last 'a' to 'z'
        return s[:-1] + 'z'

    # Otherwise, find the contiguous block of non-'a' characters starting at first_non_a
    end = first_non_a
    while end < n and s[end] != 'a':
        end += 1

    # end is now the position after the block of non-'a' characters
    # We want to convert s[first_non_a:end] (each char decremented by 1)
    result = []
    for i in range(n):
        if first_non_a <= i < end:
            # Convert to previous character
            if s[i] == 'a':
                result.append('z')
            else:
                result.append(chr(ord(s[i]) - 1))
        else:
            result.append(s[i])

    return ''.join(result)
