def lengthOfLongestSubsequence(nums: list, target: int) -> int:
    # dp[j] = the maximum length of subsequence with sum j
    # Initialize with -1 (impossible), except dp[0] = 0
    dp = [-1] * (target + 1)
    dp[0] = 0

    for num in nums:
        # Traverse from high to low to avoid using the same element multiple times
        for j in range(target, num - 1, -1):
            if dp[j - num] != -1:
                dp[j] = max(dp[j], dp[j - num] + 1)

    return dp[target]
```

