from typing import List

def maximumSubarraySum(nums: List[int], k: int):
    n = len(nums)
    # prefix[i] = sum of nums[0..i-1]
    prefix = [0] * (n + 1)
    for i in range(n):
        prefix[i + 1] = prefix[i] + nums[i]

    # For each j, we want to find i such that |nums[i] - nums[j]| == k
    # i.e., nums[i] = nums[j] - k or nums[i] = nums[j] + k
    # Subarray sum = prefix[j+1] - prefix[i]
    # To maximize this, we want to minimize prefix[i] for a given nums[i] value

    # For each value v, store the minimum prefix[i] seen so far where nums[i] == v
    min_prefix = {}  # value -> min prefix[i] for index i where nums[i] == value

    ans = None

    for j in range(n):
        v = nums[j]
        target1 = v - k
        target2 = v + k

        # Check if we have seen target1 or target2 before (as nums[i] for some i < j)
        best = None
        if target1 in min_prefix:
            candidate = prefix[j + 1] - min_prefix[target1]
            if best is None or candidate > best:
                best = candidate
        if target2 in min_prefix:
            candidate = prefix[j + 1] - min_prefix[target2]
            if best is None or candidate > best:
                best = candidate

        if best is not None:
            if ans is None or best > ans:
                ans = best

        # Update min_prefix for current value v
        if v in min_prefix:
            if prefix[j] < min_prefix[v]:
                min_prefix[v] = prefix[j]
        else:
            min_prefix[v] = prefix[j]

    return ans if ans is not None else 0
